window.HLA_SEARCH_INDEX=[{"title":"首頁","url":"index.html","type":"其他","description":"理然全球法律事務所位於臺北市大安區，提供企業法律顧問、民事訴訟、刑事辯護、家事繼承、不動產、勞資、科技智財與跨境法律服務，從事實與文件討論處理方向。"},{"title":"關於理然","url":"about.html","type":"其他","description":"認識理然全球法律事務所的定位與工作方式：以國際視野、在地實務和清楚溝通，回應企業與個人的法律需求。"},{"title":"品牌理念","url":"philosophy.html","type":"其他","description":"理解理然的品牌理念：尊重事實、重視證據與人的需求，將理性洞見、策略思維及實務深度落實於法律工作。"},{"title":"服務方法","url":"approach.html","type":"其他","description":"從理解問題、分析證據、制定策略到執行與調整，了解理然如何以五個步驟整理法律需求與下一步。"},{"title":"專業領域","url":"expertise.html","type":"其他","description":"瀏覽理然八大專業領域，包括企業與商務、民商事爭議、跨境、不動產、刑事、家事、勞動與智慧財產科技。"},{"title":"企業與商務","url":"corporate.html","type":"專業領域","description":"企業法律顧問 公司律師、股東爭議、契約審閱 理然全球法律事務所位於臺北市大安區，提供企業法律顧問、公司治理、契約審閱、股東爭議與交易法律服務，協助企業釐清決策權限、履行節點與風險。"},{"title":"民商事爭議","url":"disputes.html","type":"專業領域","description":"民事訴訟律師 債務糾紛、損害賠償、假扣押 理然全球法律事務所於臺北市大安區提供民事訴訟、債務糾紛、契約違約、損害賠償及財產保全法律服務，從證據、期限與執行可能性規劃處理方向。"},{"title":"跨境與國際爭議","url":"cross-border.html","type":"專業領域","description":"跨境法律服務 跨境契約、國際商務、管轄與準據法 理然全球法律事務所位於臺北市大安區，協助跨境契約、國際商務與涉外爭議，從交易主體、管轄、準據法及資產位置整理法律需求。"},{"title":"土地與不動產","url":"real-estate.html","type":"專業領域","description":"台北不動產律師 共有土地分割、租賃糾紛、繼承登記 理然全球法律事務所位於臺北市大安區，提供不動產交易、共有土地分割、房屋租賃、使用補償及繼承不動產法律服務，從登記、權利與現況整理爭議。"},{"title":"刑事與企業刑事","url":"criminal.html","type":"專業領域","description":"台北刑事律師 刑事辯護、偵查陪同、詐欺案件 理然全球法律事務所位於臺北市大安區，提供刑事辯護、警詢及偵查陪同、搜索扣押與刑事審判法律服務，協助釐清詐欺、財產犯罪及企業刑事案件。"},{"title":"家事與財富傳承","url":"family-wealth.html","type":"專業領域","description":"台北家事律師 離婚律師、監護權、繼承律師 理然全球法律事務所位於臺北市大安區，提供離婚、子女親權與扶養費、夫妻財產、繼承及遺產分割法律服務，協助整理家庭關係、文件與長期生活安排。"},{"title":"勞動與人力資源","url":"employment.html","type":"專業領域","description":"台北勞資爭議律師 勞動契約、工作規則、資遣離職 理然全球法律事務所位於臺北市大安區，提供勞資爭議、勞動契約、工作規則、薪資與離職交接法律服務，協助企業與個人整理文件及處理方向。"},{"title":"智慧財產與科技","url":"ip-technology.html","type":"專業領域","description":"智慧財產與科技律師 著作權授權、個資、生成式AI 理然全球法律事務所位於臺北市大安區，提供著作權、授權契約、營業秘密、個資與生成式 AI 使用法律服務，協助盤點素材、資料流與產品條款。"},{"title":"律師團隊","url":"people.html","type":"其他","description":"認識李欣庭、鄭典顥與劉添錫，了解理然的策略整合、刑事辯護及資深實務視角。"},{"title":"李欣庭律師","url":"li-hsin-ting.html","type":"律師","description":"李欣庭律師為理然全球法律事務所所長，關注企業治理、跨境爭議與重大債務及交易問題。"},{"title":"鄭典顥律師","url":"cheng-tien-hao.html","type":"律師","description":"鄭典顥律師畢業於台北大學法律學系，現為理然全球法律事務所受雇律師，重視刑事辯護中的程序正義與基本權利。"},{"title":"劉添錫律師","url":"liu-tien-hsi.html","type":"律師","description":"劉添錫律師具有長年實務經驗，為慈律律師事務所所長及理然全球法律事務所專業資深顧問。"},{"title":"法律觀點","url":"insights.html","type":"其他","description":"理然法律觀點第1頁，共32篇文章；依家事與財富、不動產、刑事程序、企業與投資、民商爭議、跨境、勞動與科技智財瀏覽，並連結對應法律服務與作者。"},{"title":"LawAI","url":"lawai.html","type":"其他","description":"LawAI 法詢協助整理事實、時間軸與文件缺口，讓問題更有結構；律師核實資料、評估法律與策略。探索平台或預約理然法律諮詢。"},{"title":"預約諮詢","url":"consultation.html","type":"其他","description":"透過理然全球法律事務所線上預約表單，整理法律議題、案件階段與諮詢需求，送出申請後由事務所聯繫確認。"},{"title":"聯絡我們","url":"contact.html","type":"其他","description":"理然全球法律事務所位於臺北市大安區敦化南路一段294號4樓之3，電話（02）2700-0677，週一至週五09:00–18:00。查看辦公室實景、交通導航、停車查詢與預約提醒。"},{"title":"搜尋","url":"search.html","type":"其他","description":"搜尋理然網站的專業領域、律師資訊、法律觀點與其他頁面。"},{"title":"隱私權政策","url":"privacy.html","type":"其他","description":"了解理然全球法律事務所如何處理聯絡資料、諮詢摘要、瀏覽資訊與第三方服務，以及個人資料權利的行使方式。"},{"title":"網站使用條款","url":"terms.html","type":"其他","description":"理然全球法律事務所網站使用條款：網站用途、合法使用、著作權、外部服務、初步聯繫與委任關係，以及適用法律。"},{"title":"法律聲明","url":"disclaimer.html","type":"其他","description":"理然全球法律事務所法律聲明：一般法律資訊、個案判斷、委任關係、程序期限、圖像與外部服務的使用範圍。"},{"title":"從契約到執行：企業如何建立清楚的法律決策流程","url":"article.html","type":"法律觀點","description":"企業契約管理 企業契約不是簽完就結束。從誰有權決定、哪個版本生效，到付款、交付與驗收如何接續，每一個節點都影響交易能否落地。本文以決策、文件和執行三條線，整理企業在交易前後可核對的問題與資料，協助團隊在爭議出現前留下清楚的依據。","category":"企業與投資"},{"title":"公司決策權限，應如何留下可追溯紀錄","url":"article-governance.html","type":"法律觀點","description":"公司決策權限 公司決策要能被理解，也要能被追溯。當股東、董事、經理人與專案團隊各自參與同一件事，單一簽名或會議紀錄往往不足以說明決定如何形成。本文從權限、程序、文件與執行四個面向，整理企業如何留下清楚紀錄，以及組織變動時應重新檢查的地方。","category":"企業與投資"},{"title":"交易文件與履行節點的整理方法","url":"article-transaction.html","type":"法律觀點","description":"交易文件與履行節點 商務交易常在簽署後才真正進入複雜階段。交付、付款、驗收、通知與變更可能由不同團隊負責，若版本和期限沒有共同基準，契約承諾便難以落實。本文提供一套文件清單與時間軸的整理方式，協助企業辨認履行中的落差、保存證據，並在必要時有序處理爭議。","category":"企業與投資"},{"title":"爭議發生前，先確認風險分配","url":"article-risk.html","type":"法律觀點","description":"契約風險分配 爭議往往在履約過程中逐漸形成，而非某一天突然發生。交期延後、品質變動、資訊不對稱與付款困難，若沒有預先安排通知、補救和退出路徑，會放大損失與誤解。本文討論如何從具體交易情境辨識風險，設計有先後順序的處理機制，並保存可用的證據。","category":"企業與投資"},{"title":"不動產交易前，如何整理權利與文件","url":"article-property.html","type":"法律觀點","description":"不動產交易權利查核 不動產交易不能只看現場，也不能只看契約。登記權利、共有或使用安排、租賃現況與交屋條件，可能指向不同的風險。本文以權利、現況、文件和交易節點為順序，整理交易前可核對的資料，並說明付款與移轉如何與驗收、點交互相銜接。","category":"不動產"},{"title":"繼承安排先從哪些資料開始整理","url":"article-inheritance.html","type":"法律觀點","description":"繼承資料準備 繼承安排同時涉及身分關係、財產負債與家人的生活需求。若一開始只談分配比例，卻沒有共同可核對的資料，討論容易陷入各自的記憶與期待。本文從關係人、資產與文件盤點開始，說明如何把法律問題、照顧需求和可執行的安排放在同一張圖上。","category":"家事與財富"},{"title":"從招募到離職：勞動制度的文件節點","url":"article-employment.html","type":"法律觀點","description":"勞動制度文件 勞動關係從招募、任用、考核、異動到離職，並非數份彼此獨立的文件。工作條件、規則與日常做法若不一致，爭議時很難說明決策的基礎。本文以工作旅程為線索，整理企業和工作者可核對的文件節點、溝通紀錄，以及重大處置前應先確認的事實。","category":"勞動"},{"title":"產品上線前，如何檢視資料、授權與平台條款","url":"article-technology.html","type":"法律觀點","description":"產品上線法律檢查 數位產品上線前，法律問題已嵌在素材來源、開發分工、資料流及使用者介面裡。只在最後套用一份條款，未必能反映產品真正如何取得、處理與分享資訊。本文從權利來源、授權邊界、個資與平台承諾，整理團隊可在設計和營運流程中持續檢查的事項。","category":"科技智財"},{"title":"股東意見分歧時，如何重建公司決策過程","url":"article-shareholder.html","type":"法律觀點","description":"股東爭議處理 股東之間對方向有分歧時，先區分經營意見、法定決議與個人權利。本文從章程、會議資料、授權與後續執行四條線，整理如何重建決策過程、辨識利益衝突及保存證據，並說明在協商或程序開始前，哪些問題應先讓專業人士核對。","category":"企業與投資"},{"title":"爭議發生前後，證據與時間軸如何保存","url":"article-evidence.html","type":"法律觀點","description":"爭議證據如何保存 民商事爭議往往不是缺少主張，而是缺少能還原交易與履行過程的資料。本文以契約、通知、付款、交付與電子往來為線索，說明爭議初期如何建立時間軸、保存原始檔、辨識證據缺口，以及何時需同步評估保全、協商與程序期限，並避免資料在過程中流失。","category":"民商爭議"},{"title":"跨境契約的管轄與準據法，先問哪些問題","url":"article-jurisdiction.html","type":"法律觀點","description":"跨境契約管轄準據法 跨境契約的爭議不只在於用哪一國法律，也包括由誰處理、如何送達、用什麼語言證明事實，以及結果能否在資產所在地落實。本文從交易結構與文件出發，整理管轄、準據法、程序與執行的不同層次，協助團隊在簽署前提出正確問題。","category":"跨境"},{"title":"買房附車位：從登記到使用權的檢查順序","url":"article-parking.html","type":"法律觀點","description":"買房車位權利 購屋時所說的「專屬車位」，可能涉及所有權、共有部分、約定專用與實際管理等不同層次。本文整理車位相關的登記、買賣契約、銷售說明、管理規約與使用現況，說明如何先釐清權利範圍，再討論交付、使用或後續爭議處理。","category":"不動產"},{"title":"收到偵查通知後，第一步先整理什麼","url":"article-investigation.html","type":"法律觀點","description":"收到偵查通知怎麼辦 收到偵查通知、搜索或扣押資訊時，最容易在急迫中遺漏時間、文件與程序權利。本文整理初期可以做的資料保存、通知核對與事件記錄，區分個人與企業的不同準備工作；任何具體應對仍應由律師依程序狀態及完整事實判斷。","category":"刑事程序"},{"title":"分開居住後，子女照顧安排如何具體化","url":"article-childcare.html","type":"法律觀點","description":"分居後子女照顧安排 家庭關係改變時，孩子的日常照顧、就學、探視與費用安排往往比抽象原則更迫切。本文從生活時程與重要文件出發，整理共同討論的事項、協議可執行性的檢查方法，以及衝突升高時如何保留溝通紀錄並尋求合適的專業協助。","category":"家事與財富"},{"title":"生成式 AI 作品的素材來源與授權怎麼查","url":"article-ai-rights.html","type":"法律觀點","description":"生成式AI素材授權 生成式 AI 進入設計、行銷與產品流程後，企業需要同時追問素材來源、輸入權限、輸出使用與客戶交付。本文以一項創作專案為例，整理著作權與契約的檢查順序，以及團隊如何保留人類創作、授權與資料流的紀錄，而非對所有 AI 成果作單一結論。","category":"科技智財"},{"title":"員工離職與營業秘密：從權限到交接","url":"article-secrets.html","type":"法律觀點","description":"員工離職營業秘密 員工離職交接常同時牽涉工作成果、客戶資料與企業希望保護的資訊。本文從「資料是否具保護基礎」與「誰有權存取、如何交接」兩條線，整理日常權限管理、離職前後的紀錄，以及發現異常時如何保全資料與避免過度蒐集。","category":"勞動"},{"title":"離婚要先協議、調解，還是提起訴訟？","url":"article-divorce-options.html","type":"法律觀點","description":"離婚方式比較 考慮離婚時，最先需要決定的往往不是訴狀怎麼寫，而是雙方是否能安全溝通、哪些事項已達成共識，以及子女與財產安排能否真正執行。本文區分協議、法院調解與裁判離婚，整理文件、證據與程序的準備順序，協助您在情緒與時間壓力中，仍能清楚評估下一步。","category":"家事與財富"},{"title":"離婚時的剩餘財產分配：先整理哪些資產與負債","url":"article-divorce-property.html","type":"法律觀點","description":"離婚剩餘財產分配 離婚時談財產，不能只問房子登記在誰名下，也不能把所有資產直接除以二。剩餘財產分配涉及夫妻財產制、取得時間、資金來源、債務與計算基準。本文整理資料盤點、權利區分及協商前的核對方法，讓財產討論從可查證的項目開始，而不是停留在總額與印象。","category":"家事與財富"},{"title":"子女扶養費怎麼計算？從生活支出到父母分擔","url":"article-child-support.html","type":"法律觀點","description":"扶養費怎麼算 子女扶養費沒有適用所有家庭的固定價目表。孩子的實際需要、父母經濟能力、既有照顧分工與可提出的資料，都會影響討論方式。本文從每月支出清單開始，區分日常費用、特殊支出及履行安排，並說明如何把抽象的分擔比例，轉成雙方能理解、也能持續執行的方案。","category":"家事與財富"},{"title":"對方不付扶養費：催告、調解與強制執行的順序","url":"article-support-enforcement.html","type":"法律觀點","description":"不付扶養費怎麼辦 對方停止支付扶養費時，先確認手上的是私下協議、調解筆錄，還是法院裁判，才能決定下一步。本文整理欠款明細、執行名義及財產資料的核對方式，區分催告、取得裁判與聲請執行的不同功能，避免反覆傳訊息，卻錯過真正需要處理的文件與程序。","category":"家事與財富"},{"title":"親權與主要照顧安排：把子女最佳利益說清楚","url":"article-custody.html","type":"法律觀點","description":"子女親權判斷 親權爭議不是父母之間的勝負，也不只比較誰收入較高。法院關注的是孩子的最佳利益，以及安排能否維持穩定、適齡與安全的生活。本文把抽象原則轉成照顧時程、健康教育、親子關係及協作能力等具體資料，協助父母整理可被理解的方案，而不讓孩子承擔選邊的壓力。","category":"家事與財富"},{"title":"會面交往如何安排？接送、假日與履行困難","url":"article-visitation.html","type":"法律觀點","description":"會面交往安排 會面交往不只是寫下每月見幾次。孩子作息、父母距離、接送責任、重要節日與臨時狀況，都會影響安排能否持續。本文從一份可執行的生活計畫出發，整理協議細節、聯繫方式與履行困難的處理順序，讓親子關係在家庭變化後仍有穩定的連結。","category":"家事與財富"},{"title":"繼承遇到債務：限定責任、拋棄繼承與遺產清冊","url":"article-inheritance-debt.html","type":"法律觀點","description":"繼承債務怎麼辦 接到親人過世後留下的貸款或催收通知，最重要的是先確認繼承開始、知悉日期與債務資料，而不是急著用自己的存款還款。限定清償責任、拋棄繼承及提出遺產清冊，功能與法律效果不同。本文整理期限、查詢與文件準備，協助家屬在資訊尚未完整時，避免因錯誤處分增加原本可以控制的風險。","category":"家事與財富"},{"title":"遺產分割談不攏：從共同盤點到分割程序","url":"article-estate-division.html","type":"法律觀點","description":"遺產分割談不攏 遺產分配發生分歧，往往不只是比例問題。誰是繼承人、哪些財產屬於遺產、是否有債務或遺囑，以及先前由誰管理，都會影響可以討論的方案。本文從共同清單開始，整理協議、調解與法院分割的差異，讓家屬先建立同一份事實基礎，再決定如何結束共同持有的狀態。","category":"家事與財富"},{"title":"遺囑與特留分：傳承安排不能只看分配比例","url":"article-will-reserved-share.html","type":"法律觀點","description":"遺囑與特留分 想透過遺囑安排財產，除了決定誰取得什麼，還要確認法定形式、可處分範圍、特留分與執行方式。特留分法規另有已公布但尚未生效的修正，更不能只看搜尋結果中的最新文字。本文整理立遺囑前的盤點及核對順序，讓傳承安排同時顧及法律效力、家庭需要與日後履行。","category":"家事與財富"},{"title":"共有繼承不動產：繼承登記、管理與分割怎麼銜接","url":"article-inheritance-registration.html","type":"法律觀點","description":"共有繼承不動產登記 親人留下房屋或土地，辦理繼承登記與決定如何分配，是不同階段。有人住在房子裡、有人付稅或代繳貸款，也不代表可以直接取得全部所有權。本文整理登記、共有管理及分割的銜接，讓家屬知道哪些事項可以先處理，哪些需要共同協議，避免房產長期停留在無人負責的狀態。","category":"不動產"},{"title":"共有土地怎麼分割？原物、變價與補償的比較","url":"article-land-partition.html","type":"法律觀點","description":"共有土地分割 共有土地的持分，通常不是地面上某一塊已經劃好的區域。希望結束共有時，必須同時考慮登記、法令限制、出入通路、現況與價值。本文比較原物分割、變價分配及金錢補償，整理協商與法院程序所需資料，讓共有人提出的是能實際使用與登記的方案，而不是只在地圖上畫線。","category":"不動產"},{"title":"共有人要出售土地：同意比例與優先承購怎麼確認","url":"article-coowner-sale.html","type":"法律觀點","description":"共有人出售土地 部分共有人想出售土地、另一些人不同意，不能只用「多數決」三個字判斷能否交易。出售整筆共有不動產與出售個人持分，程序及優先承購問題不同。本文整理土地法第34條之1的比例、通知與交易條件，協助當事人先確認權限與文件，再決定出售、承購或提出異議的方式。","category":"不動產"},{"title":"共有房屋被一人使用：管理、費用與使用補償","url":"article-shared-use.html","type":"法律觀點","description":"共有房屋一人使用 共有房屋由一人居住或出租，其他共有人是否可以要求搬離、分租金或支付補償，不能只看誰實際使用。持分、分管約定、管理決定及取得方式，都會影響權利。本文整理使用與費用的核對方法，協助共有人把長期不滿轉成具體的資料與方案，而不是只在房門與帳單前反覆爭執。","category":"不動產"},{"title":"房客不搬離時：終止租約、返還房屋與點交","url":"article-rental-return.html","type":"法律觀點","description":"房客不搬怎麼辦 租約到期或房客違反約定，不代表房東可以立刻換鎖取回房屋。是否有效終止、應如何通知、返還請求與點交方式，都要對照契約、實際履行與適用法規。本文整理從欠款、催告到返還與執行的順序，協助雙方以完整紀錄處理爭議，避免自力排除造成更多風險。","category":"不動產"},{"title":"第一次警詢前，先認識陳述權利與證據保存","url":"article-criminal-rights.html","type":"法律觀點","description":"第一次警詢注意事項 收到警察通知，先確認到場身分、通知內容與時間，再決定如何準備。犯罪嫌疑人、被告、證人或告訴人的程序位置不同，陳述與權利也不能混用。本文整理警詢前的文件、緘默與辯護權、筆錄核對及證據保存，讓第一次面對程序的人，能在了解問題後作出自己的決定。","category":"刑事程序"},{"title":"網路交易遇到詐騙：從金流與對話整理報案資料","url":"article-online-fraud.html","type":"法律觀點","description":"網路交易被詐騙報案 網路購物、投資或借貸出現異常時，先停止追加款項、保存金流與對話，再透過正式管道求助。對方未履約不一定就是刑事詐騙，但也不能因為仍在回訊息就忽略風險。本文整理查證、報案與民事追償的資料順序，讓受害者在急迫情緒中仍能留下可供調查的完整線索。","category":"刑事程序"}];
